function extractSqliteCreateTableBlocks(sqlText) {
  const tables = []
  let pos = 0
  const upper = sqlText.toUpperCase()
  while (pos < sqlText.length) {
    const createIdx = upper.indexOf('CREATE TABLE', pos)
    if (createIdx === -1) break
    const openParen = sqlText.indexOf('(', createIdx)
    if (openParen === -1) break
    let depth = 1
    let cur = openParen + 1
    let inQuote = false
    let quoteChar = ''
    while (cur < sqlText.length && depth > 0) {
      const ch = sqlText[cur]
      if (inQuote) {
        if (ch === quoteChar) inQuote = false
      } else if (ch === "'" || ch === '"' || ch === '`') {
        inQuote = true
        quoteChar = ch
      } else if (ch === '(') depth++
      else if (ch === ')') depth--
      cur++
    }
    if (depth === 0) {
      tables.push(sqlText.slice(createIdx, cur).trim())
      pos = cur
    } else pos = openParen + 1
  }
  return tables
}

// 1. Extract PostgreSQL Schemas (79 tables)
const pgDir = path.join(rootDir, 'cloud-server/src/db')
const schemaSql = fs.readFileSync(path.join(pgDir, 'schema.sql'), 'utf8')
const pgTables = LexicalSqlParser.parseTables(schemaSql)

const migDir = path.join(pgDir, 'migrations')
if (fs.existsSync(migDir)) {
  const migFiles = fs
    .readdirSync(migDir)
    .filter((f) => f.endsWith('.sql'))
    .sort()
  for (const f of migFiles) {
    const migSql = fs.readFileSync(path.join(migDir, f), 'utf8')
    const migParsed = LexicalSqlParser.parseTables(migSql)
    for (const [k, v] of migParsed) {
      if (!pgTables.has(k)) {
        pgTables.set(k, v)
      } else {
        const existing = pgTables.get(k)
        for (const col of v.columns) {
          if (!existing.columns.some((c) => c.name === col.name)) {
            existing.columns.push(col)
          }
        }
        if (!existing.primaryKey && v.primaryKey) existing.primaryKey = v.primaryKey
        existing.uniqueKeys.push(...v.uniqueKeys)
        existing.foreignKeys.push(...v.foreignKeys)
      }
    }
  }
}

// 2. Extract SQLite Schemas (83 tables)
const sqliteTables = new Map()
function mergeSqlite(sql) {
  const parsed = LexicalSqlParser.parseTables(sql)
  for (const [k, v] of parsed) {
    if (!sqliteTables.has(k)) {
      sqliteTables.set(k, v)
    } else {
      const existing = sqliteTables.get(k)
      for (const col of v.columns) {
        if (!existing.columns.some((c) => c.name === col.name)) {
          existing.columns.push(col)
        }
      }
      if (!existing.primaryKey && v.primaryKey) existing.primaryKey = v.primaryKey
      existing.uniqueKeys.push(...v.uniqueKeys)
      existing.foreignKeys.push(...v.foreignKeys)
    }
  }
}

const ddlSql = path.join(b2bDir, 'cloud-migration/schema_ddl.sql')
if (fs.existsSync(ddlSql)) {
  const blocks = extractSqliteCreateTableBlocks(fs.readFileSync(ddlSql, 'utf8'))
  mergeSqlite(blocks.join(';\n'))
}

const legalTs = path.join(b2bDir, 'src/main/db/legalServicesSchema.ts')
if (fs.existsSync(legalTs)) {
  const blocks = extractSqliteCreateTableBlocks(fs.readFileSync(legalTs, 'utf8'))
  mergeSqlite(blocks.join(';\n'))
}

const dbTs = path.join(b2bDir, 'src/main/db/database.ts')
if (fs.existsSync(dbTs)) {
  const dbContent = fs.readFileSync(dbTs, 'utf8')
  const blocks = extractSqliteCreateTableBlocks(dbContent)
  mergeSqlite(blocks.join(';\n'))
  // Parse addColumn statements
  const addColRegex = /addColumn\(\s*['"]([a-zA-Z0-9_]+)['"]\s*,\s*['"]([a-zA-Z0-9_]+)['"]\s*,\s*['"]([^'"]+)['"]\s*\)/g
  let m
  while ((m = addColRegex.exec(dbContent)) !== null) {
    const tName = m[1].toLowerCase()
    const colName = m[2].toLowerCase()
    if (sqliteTables.has(tName)) {
      const existing = sqliteTables.get(tName)
      if (!existing.columns.some((c) => c.name === colName)) {
        existing.columns.push({ name: colName, isPrimaryKey: false, isNullable: true })
      }
    }
  }
}

const migSql = path.join(b2bDir, 'cloud-migration/migration_company_id.sql')
if (fs.existsSync(migSql)) {
  const content = fs.readFileSync(migSql, 'utf8')
  const alterRegex = /ALTER\s+TABLE\s+([a-zA-Z0-9_]+)\s+ADD\s+COLUMN\s+company_id/gi
  let m
  while ((m = alterRegex.exec(content)) !== null) {
    const tName = m[1].toLowerCase()
    if (!sqliteTables.has(tName)) {
      sqliteTables.set(tName, {
        tableName: tName,
        columns: [
          { name: 'id', isPrimaryKey: true, isNullable: false },
          { name: 'company_id', isPrimaryKey: false, isNullable: false }
        ],
        primaryKey: ['id'],
        uniqueKeys: [],
        foreignKeys: []
      })
    } else {
      const existing = sqliteTables.get(tName)
      if (!existing.columns.some((c) => c.name === 'company_id')) {
        existing.columns.push({ name: 'company_id', isPrimaryKey: false, isNullable: false })
      }
    }
  }
}

