function classifyEntity(name) {
  const sensitive = [...SENSITIVE_ENTITIES]
  if (sensitive.includes(name)) return 'excluded_sensitive'

  if (AUDIT_ENTITIES.has(name)) return 'system_audit'

  if (SYSTEM_REFERENCE_ENTITIES.has(name)) return 'system_reference'

  const cloudOnly = ['tenants', 'tenant_memberships', 'tenant_subscriptions', 'subscriptions', 'plans', 'invoices_cloud', 'payments']
  if (cloudOnly.includes(name)) return 'platform_only_cloud'

  return 'business_entity'
}

function getTenantScope(name, columns) {
  if (columns.includes('company_id')) return { kind: 'column', column: 'company_id' }
  if (name === 'companies') return { kind: 'root_id', column: 'id' }
  const indirect = INDIRECT_TENANT_OWNERSHIP[name]
  if (indirect && columns.includes(indirect.localColumn)) return { kind: 'parent', ...indirect }
  return { kind: 'global' }
}

function getSensitiveColumns(columns) {
  return columns.filter((column) => SENSITIVE_COLUMNS.has(column))
}

function buildBindingBlock(binding) {
  const lines = []
  lines.push(`    tableName: ${JSON.stringify(binding.tableName)},`)
  lines.push(`    primaryKey: ${JSON.stringify(binding.primaryKey)},`)
  lines.push(`    ownershipColumn: ${JSON.stringify(binding.ownershipColumn)},`)
  lines.push(`    tenantScope: ${JSON.stringify(binding.tenantScope)},`)
  lines.push(`    columns: ${JSON.stringify(binding.columns)},`)
  lines.push(`    requiredColumns: ${JSON.stringify(binding.requiredColumns)},`)
  lines.push(`    nullableColumns: ${JSON.stringify(binding.nullableColumns)},`)
  lines.push(`    uniqueKeys: ${JSON.stringify(binding.uniqueKeys)},`)
  lines.push(`    foreignKeys: ${JSON.stringify(binding.foreignKeys)},`)
  lines.push(`    allowedExportColumns: ${JSON.stringify(binding.allowedExportColumns)},`)
  lines.push(`    allowedImportColumns: ${JSON.stringify(binding.allowedImportColumns)}`)
  lines[lines.length - 1] += `,`
  lines.push(`    sensitiveColumns: ${JSON.stringify(binding.sensitiveColumns)}`)
  return lines.join('\n')
}

lines.push(`export const CANONICAL_CONTRACT_REGISTRY: Record<string, CanonicalEntityContract> = {`)

for (const name of sortedNames) {
  const pg = pgTables.get(name)
  const sqlite = sqliteTables.get(name)
  const classification = classifyEntity(name)
  const attachmentStorage = ATTACHMENT_STORAGE[name]
  const isAppendOnly = APPEND_ONLY_ENTITIES.has(name)
  const pgScope = pg ? getTenantScope(name, pg.columns.map((column) => column.name)) : null
  const sqliteScope = sqlite
    ? getTenantScope(name, sqlite.columns.map((column) => column.name))
    : null
  const scopes = [pgScope, sqliteScope].filter(Boolean)
  const scopeKinds = new Set(scopes.map((scope) => scope.kind))
  const ownershipPolicy =
    scopeKinds.size > 1
      ? 'platform_mixed'
      : scopeKinds.has('column')
        ? 'company_id_required'
        : scopeKinds.has('root_id')
          ? 'tenant_root_id'
          : scopeKinds.has('parent')
            ? 'parent_join_required'
            : 'global_system'
  const tenantScoped = scopes.some((scope) => scope.kind !== 'global')
  const exportPolicy =
    classification === 'excluded_sensitive' || classification.startsWith('platform_only')
      ? 'no_export'
      : classification === 'system_reference'
        ? 'system_export'
        : tenantScoped
          ? 'tenant_export'
          : 'no_export'
  const restorePolicy =
    exportPolicy === 'tenant_export'
      ? 'tenant_restore'
      : exportPolicy === 'system_export'
        ? 'system_restore'
        : 'no_restore'

  lines.push(`  ${JSON.stringify(name)}: {`)
  lines.push(`    canonicalName: ${JSON.stringify(name)},`)
  lines.push(`    classification: ${JSON.stringify(classification)},`)
  lines.push(`    exportPolicy: ${JSON.stringify(exportPolicy)},`)
  lines.push(`    restorePolicy: ${JSON.stringify(restorePolicy)},`)
  lines.push(`    tenantOwnershipPolicy: ${JSON.stringify(ownershipPolicy)},`)
  lines.push(`    isAppendOnly: ${isAppendOnly},`)
  lines.push(`    supportsAttachments: ${Boolean(attachmentStorage)},`)
  if (attachmentStorage) {
    lines.push(`    attachmentCategory: ${JSON.stringify(name)},`)
    lines.push(`    attachmentStorage: ${JSON.stringify(attachmentStorage)},`)
  }
  
  // Topological dependencies
  const deps = new Set()
  if (pg) {
    for (const fk of pg.foreignKeys) {
      const target = fk.targetTable || fk.referencesTable
      if (target && target !== name && (pgTables.has(target) || sqliteTables.has(target))) {
        deps.add(target)
      }
    }
  }
  if (sqlite) {
    for (const fk of sqlite.foreignKeys) {
      const target = fk.targetTable || fk.referencesTable
      if (target && target !== name && (pgTables.has(target) || sqliteTables.has(target))) {
        deps.add(target)
      }
    }
  }
  lines.push(`    dependencies: ${JSON.stringify([...deps].sort())},`)
  const allColumns = [...new Set([...(pg?.columns || []), ...(sqlite?.columns || [])].map((c) => c.name))]
  const immutableColumns = isAppendOnly
    ? allColumns
    : [...new Set(['id', 'company_id', 'created_at'].filter((column) => allColumns.includes(column)))]
  lines.push(`    immutableColumns: ${JSON.stringify(immutableColumns)},`)
  lines.push(`    conflictStrategy: ${JSON.stringify(isAppendOnly ? 'skip' : 'upsert')},`)
  lines.push(`    deletionStrategy: ${JSON.stringify(isAppendOnly ? 'append_only' : allColumns.includes('is_deleted') ? 'soft_delete' : 'tombstone')},`)
  lines.push(`    syncPolicy: ${JSON.stringify(exportPolicy !== 'tenant_export' ? 'no_sync' : pg && sqlite ? 'bidirectional' : pg ? 'server_authoritative' : 'desktop_only')},`)
  lines.push(`    stableIdStrategy: 'preserve_source_identifier',`)
  lines.push(`    schemaVersionIntroduced: 3,`)
  lines.push(`    legacyMigrationAdapter: ${JSON.stringify(exportPolicy === 'tenant_export' ? 'canonical_field_projection_v1' : 'none')},`)

  if (pg) {
    const rawCols = pg.columns.map((c) => c.name)
    const validCols = rawCols.filter((c) => /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(c))
    const pks = (Array.isArray(pg.primaryKey) ? pg.primaryKey : [pg.primaryKey]).filter(Boolean)
    const hasCompanyPg = validCols.includes('company_id')
    const ownership = hasCompanyPg ? 'company_id' : null
    const tenantScope = getTenantScope(name, validCols)

    const req = pg.columns
      .filter((c) => (!c.isNullable || pks.includes(c.name)) && validCols.includes(c.name))
      .map((c) => c.name)
      .sort()
    const nulls = pg.columns
      .filter((c) => c.isNullable && !pks.includes(c.name) && validCols.includes(c.name))
      .map((c) => c.name)
      .sort()

    // Filter export columns to strictly only valid cols excluding sensitive auth columns
    const sensitiveColumns = getSensitiveColumns(validCols)
    const expCols = validCols.filter((c) => !sensitiveColumns.includes(c))

    const pgFks = (pg.foreignKeys || []).map((fk) => ({
      column: fk.column,
      targetTable: fk.targetTable || fk.referencesTable || '',
      targetColumn: fk.targetColumn || fk.referencesColumn || 'id'
    }))

    lines.push(`    pgBinding: {`)
    lines.push(
      buildBindingBlock({
        tableName: name,
        primaryKey: pks,
        ownershipColumn: ownership,
        tenantScope,
        columns: validCols,
        requiredColumns: req,
        nullableColumns: nulls,
        uniqueKeys: pg.uniqueKeys || [],
        foreignKeys: pgFks,
        allowedExportColumns: expCols,
        allowedImportColumns: expCols,
        sensitiveColumns
      })
    )
    lines.push(`    },`)
  }

  if (sqlite) {
    const rawCols = sqlite.columns.map((c) => c.name)
    const validCols = rawCols.filter((c) => /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(c))
    const pks = (Array.isArray(sqlite.primaryKey) ? sqlite.primaryKey : [sqlite.primaryKey]).filter(
      Boolean
    )
    const hasCompanySqlite = validCols.includes('company_id')
    const ownership = hasCompanySqlite ? 'company_id' : null
    const tenantScope = getTenantScope(name, validCols)

    const req = sqlite.columns
      .filter((c) => (!c.isNullable || pks.includes(c.name)) && validCols.includes(c.name))
      .map((c) => c.name)
      .sort()
    const nulls = sqlite.columns
      .filter((c) => c.isNullable && !pks.includes(c.name) && validCols.includes(c.name))
      .map((c) => c.name)
      .sort()

    const sensitiveColumns = getSensitiveColumns(validCols)
    const expCols = validCols.filter((c) => !sensitiveColumns.includes(c))

    const sqliteFks = (sqlite.foreignKeys || []).map((fk) => ({
      column: fk.column,
      targetTable: fk.targetTable || fk.referencesTable || '',
      targetColumn: fk.targetColumn || fk.referencesColumn || 'id'
    }))

    lines.push(`    sqliteBinding: {`)
    lines.push(
      buildBindingBlock({
        tableName: name,
        primaryKey: pks,
        ownershipColumn: ownership,
        tenantScope,
        columns: validCols,
        requiredColumns: req,
        nullableColumns: nulls,
        uniqueKeys: sqlite.uniqueKeys || [],
        foreignKeys: sqliteFks,
        allowedExportColumns: expCols,
        allowedImportColumns: expCols,
        sensitiveColumns
      })
    )
    lines.push(`    },`)
  }

  lines.push(`  },`)
}

