lines.push(``)
lines.push(`export function getTopologicallySortedContracts(): CanonicalEntityContract[] {`)
lines.push(`  const contracts = Object.values(CANONICAL_CONTRACT_REGISTRY);`)
lines.push(`  const contractMap = new Map(contracts.map((c) => [c.canonicalName, c]));`)
lines.push(`  const visited = new Set<string>();`)
lines.push(`  const visiting = new Set<string>();`)
lines.push(`  const result: CanonicalEntityContract[] = [];`)
lines.push(``)
lines.push(`  function visit(name: string) {`)
lines.push(`    if (visited.has(name)) return;`)
lines.push(`    if (visiting.has(name)) {`)
lines.push(`      throw new Error(\`CANONICAL_DEPENDENCY_CYCLE: \${name}\`);`)
lines.push(`    }`)
lines.push(`    visiting.add(name);`)
lines.push(`    const contract = contractMap.get(name);`)
lines.push(`    if (contract) {`)
lines.push(`      for (const dep of contract.dependencies) {`)
lines.push(`        if (contractMap.has(dep)) visit(dep);`)
lines.push(`      }`)
lines.push(`      visited.add(name);`)
lines.push(`      result.push(contract);`)
lines.push(`    }`)
lines.push(`    visiting.delete(name);`)
lines.push(`  }`)
lines.push(``)
lines.push(`  for (const contract of contracts) {`)
lines.push(`    if (!visited.has(contract.canonicalName)) {`)
lines.push(`      visit(contract.canonicalName);`)
lines.push(`    }`)
lines.push(`  }`)
lines.push(``)
lines.push(`  return result;`)
lines.push(`}`)

const code = lines.join('\n')
const targetPath = path.join(rootDir, 'src/shared/canonicalContract.ts')
fs.writeFileSync(targetPath, code, 'utf8')
console.log(`Successfully generated ${targetPath}`)
